mapper.select:
SELECT , FALSE AS selected FROM wallet_ledger_entries le JOIN wallet_transfers t ON t.transfer_id = le.transfer_id JOIN wallets w ON w.wallet_id = le.wallet_id AND w.deleted_at IS NULL JOIN wallet_owners wo ON wo.wallet_owner_id = w.wallet_owner_id AND wo.member_id = #{memberId} AND wo.deleted_at IS NULL JOIN trips tr ON tr.trip_id = #{tripId} AND tr.member_id = #{memberId} AND tr.deleted_at IS NULL WHERE le.entry_type = 'DEBIT' AND le.deleted_at IS NULL AND t.initiator_member_id = #{memberId} AND t.deleted_at IS NULL AND t.currency_code = 'KRW' AND t.transfer_status = 'COMPLETED' AND t.transfer_type IN ('QR_PAYMENT', 'SETTLEMENT') AND DATE(t.completed_at) BETWEEN tr.start_date AND tr.end_date AND t.transfer_id IN
#{transferId}
FOR UPDATE
